import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../../environments/environment';
import { LocalStorageService } from '../../services/localStorage/local-storage.service';
import { VanillaDialogService } from '../../services/vanilla-dialog/vanilla-dialog.service';
import { StandarResponse } from '../../services/api/api-service.service';
import { BaseModel } from '../../models/base.model';

export interface LoginCliente extends BaseModel {
  id: number;
  email: string;
  datos_personales_id: number;
  datos_fiscal_id: number;
  negocio_id: number;
  apoyos_id: number;
  password?: string | null;
  token: string;
  update_token: string;
  tipo: 'PFAE' | 'PM';
}

@Injectable({
  providedIn: 'any'
})
export class AuthClientesService {
  private apiUrl = environment.api_url

  constructor(
    private http: HttpClient,
    private storage: LocalStorageService,
    private dialog: VanillaDialogService,
  ) { }

  public async login(email: string, password?: string) {
    const data = {
      email: email,
      password: password,
    }
    const res = await firstValueFrom(this.http.post<StandarResponse<LoginCliente>>(this.apiUrl + '/api/clientes/auth/login', { data }))
    if (!res?.status) {
      this.dialog.show({
        title: 'Algo salio mal',
        body: res?.message ?? 'Algo salio mal en el servidor, intente de nuevo o solicite asistencia de un administrador.',
        tipo: 'danger',
      })
      return
    }

    if (res.data) {
      this.storage.setClienteUser(res.data)
    }
    return res.data;
  }

  public async updatePass(oldPass: string, newPass: string) {
    const user = this.storage.getClienteUser()
    const data = {
      id: user?.id,
      old_pass: oldPass,
      new_pass: newPass,
    }
    const res = await firstValueFrom(this.http.post<StandarResponse>(this.apiUrl + '/api/clientes/auth/update', { data }))
    if (!res?.status) {
      this.dialog.show({
        title: 'Algo salio mal',
        body: res?.message ?? 'Algo salio mal en el servidor, intente de nuevo o solicite asistencia de un administrador.',
        tipo: 'danger',
      })
      return
    }

    this.dialog.show({
      title: 'Contraseña cambiada',
      body: 'La contraseñaa fue cambiada exitosamente.',
      tipo: 'success'
    })

    return res.status;
  }

}
